const DEEP_IMPORT_PREFIX = '@nx/devkit/src/';
const PUBLIC_ENTRY = '@nx/devkit';
const INTERNAL_ENTRY = '@nx/devkit/internal';

interface Bucket {
  target: string;
  isType: boolean;
  quote: string;
  /** localName -> rendered specifier text, preserving first-seen order. */
  specs: Map<string, string>;
  hasRewritten: boolean;
  contributorStarts: number[];
}

interface Edit {
  start: number;
  end: number;
  text: string;
}

/**
 * Rewrites `@nx/devkit/src/...` deep imports (and `require`/dynamic
 * `import(...)` of the same) to the canonical entry points and collapses the
 * resulting duplicate import declarations. Pure: takes source, returns source.
 */
export function rewriteDevkitDeepImports(source: string): string {
  if (!source.includes(DEEP_IMPORT_PREFIX)) {
    // Nothing to route; only the require()/import() fallback below could apply,
    // and it also keys off the deep prefix, so there is nothing to do.
    return source;
  }

  const sourceFile = ts.createSourceFile(
    'source.ts',
    source,
    ts.ScriptTarget.Latest,
    /* setParentNodes */ true,
    ts.ScriptKind.TS
